import os, subprocess, ctypes, torch, time, sys
os.makedirs('/tmp/convblk', exist_ok=True)
print('exists', os.path.exists('/tmp/convblk/kernel.cu'))
SRC = r'''
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cublasLt.h>
#include <cstdint>
#include <cstdio>
#include <map>
#include <algorithm>
#define CK(x) do { cudaError_t e_ = (x); if (e_ != cudaSuccess) return 100 + (int)e_; } while (0)
#define CB(x) do { cublasStatus_t s_ = (x); if (s_ != CUBLAS_STATUS_SUCCESS) return 200 + (int)s_; } while (0)
static __device__ __forceinline__ uint32_t pack_h2(float a, float b) { __half2 h = __floats2half2_rn(a, b); return *reinterpret_cast<uint32_t*>(&h); }
static __device__ __forceinline__ float warp_sum(float v) {
#pragma unroll
  for (int o = 16; o > 0; o >>= 1) v += __shfl_xor_sync(0xffffffffu, v, o);
  return v;
}
struct K1P {
  const float *x, *dww, *dwb, *lnw, *lnb, *w1, *gb, *w2, *b2;
  __half *a1, *w1h, *w2h;
  float* sumsq;
  int B, C, H, W, RT, TB, nTW, nTH, nrole, LD, doW2, PS;
  float eps;
};
static __device__ void k1_role(const K1P& p, int rb, int tid, int nthr) {
  const int gtid = rb * nthr + tid, gn = p.nrole * nthr;
  const int K4 = 4 * p.C;
  for (int i = gtid; i < p.B * K4; i += gn) p.sumsq[i] = 0.f;
  const long n8 = (long)K4 * p.C / 8;
  for (long i0 = gtid; i0 < n8; i0 += 4L * gn) {
    float4 v[4][2];
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      long i = i0 + (long)u * gn;
      v[u][0] = v[u][1] = make_float4(0.f, 0.f, 0.f, 0.f);
      if (i < n8) {
        const float4* s = reinterpret_cast<const float4*>(p.w1 + i * 8);
        v[u][0] = __ldg(s);
        v[u][1] = __ldg(s + 1);
      }
    }
#pragma unroll
    for (int u = 0; u < 4; ++u) {
      long i = i0 + (long)u * gn;
      if (i < n8) {
        uint4 o = make_uint4(pack_h2(v[u][0].x, v[u][0].y), pack_h2(v[u][0].z, v[u][0].w),
                             pack_h2(v[u][1].x, v[u][1].y), pack_h2(v[u][1].z, v[u][1].w));
        *reinterpret_cast<uint4*>(p.w1h + i * 8) = o;
      }
    }
  }
  if (p.doW2) {
    const int nw = nthr / 32, lane = tid & 31;
    const int gw_ = rb * nw + (tid >> 5), gnw = p.nrole * nw;
    for (int c = gw_; c < p.C; c += gnw) {
      const float* wr = p.w2 + (size_t)c * K4;
      __half* o = p.w2h + (size_t)c * p.LD;
      float dot = 0.f;
      for (int k = lane * 4; k < K4; k += 128) {
        float4 w = __ldg(reinterpret_cast<const float4*>(wr + k));
        float4 g = __ldg(reinterpret_cast<const float4*>(p.gb + k));
        dot += w.x * g.x + w.y * g.y + w.z * g.z + w.w * g.w;
        *reinterpret_cast<uint2*>(o + k) = make_uint2(pack_h2(w.x, w.y), pack_h2(w.z, w.w));
      }
      dot = warp_sum(dot);
      const float bb = p.b2[c] + dot;
      if (lane < 8) {
        __half hi = __float2half_rn(bb);
        __half v = lane == 0 ? hi : (lane == 1 ? __float2half_rn(bb - __half2float(hi)) : __float2half_rn(0.f));
        o[K4 + lane] = v;
      }
    }
  }
}
template <int WT>
__global__ void __launch_bounds__(192) k1_dwln(const K1P p) {
  extern __shared__ float sm[];
  const int tid = threadIdx.x, TB = p.TB;
  if ((int)blockIdx.x < p.nrole) { k1_role(p, blockIdx.x, tid, TB); return; }
  int t = blockIdx.x - p.nrole;
  const int tw = t % p.nTW; t /= p.nTW;
  const int th = t % p.nTH;
  const int b = t / p.nTH;
  const int C = p.C, H = p.H, W = p.W, RT = p.RT, PS = p.PS;
  const int h0 = th * RT, w0 = tw * WT;
  const int rows = min(RT, H - h0);
  constexpr int CW = WT + 6;
  const int RG = (RT + 6) * CW;
  float* pl = sm;
  float* wsm = sm + TB * PS;
  float* dsm = wsm + TB * 49;
  const int lane = tid & 31, warp = tid >> 5;
  for (int ch0 = 0; ch0 < C; ch0 += TB) {
    __syncthreads();
    for (int cl = warp * 32; cl < warp * 32 + 32; ++cl) {
      const float* xp = p.x + (size_t)(b * C + ch0 + cl) * H * W;
      float* dp = pl + cl * PS;
      for (int rem = lane; rem < RG; rem += 32) {
        const int rr = rem / CW, cc = rem - rr * CW;
        const int gh = h0 - 3 + rr, gw = w0 - 3 + cc;
        const bool ok = gh >= 0 && gh < H && gw >= 0 && gw < W;
        const float* src = ok ? xp + gh * W + gw : p.x;
        uint32_t d = (uint32_t)__cvta_generic_to_shared(dp + rem);
        asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;" :: "r"(d), "l"(src), "r"(ok ? 4 : 0));
      }
    }
    for (int e = tid; e < TB * 49; e += TB) {
      uint32_t d = (uint32_t)__cvta_generic_to_shared(wsm + e);
      asm volatile("cp.async.ca.shared.global [%0], [%1], 4;" :: "r"(d), "l"(p.dww + (size_t)ch0 * 49 + e));
    }
    asm volatile("cp.async.commit_group;");
    asm volatile("cp.async.wait_group 0;");
    __syncthreads();
    float wr[49];
    const float* wp = wsm + tid * 49;
#pragma unroll
    for (int k = 0; k < 49; ++k) wr[k] = wp[k];
    const float bias = __ldg(p.dwb + ch0 + tid);
    const float* pt = pl + tid * PS;
    for (int r = 0; r < rows; ++r) {
      float acc[WT];
#pragma unroll
      for (int w = 0; w < WT; ++w) acc[w] = bias;
#pragma unroll
      for (int i = 0; i < 7; ++i) {
        float xr[CW];
#pragma unroll
        for (int q = 0; q < CW; ++q) xr[q] = pt[(r + i) * CW + q];
#pragma unroll
        for (int j = 0; j < 7; ++j)
#pragma unroll
          for (int w = 0; w < WT; ++w) acc[w] = fmaf(xr[w + j], wr[i * 7 + j], acc[w]);
      }
#pragma unroll
      for (int w = 0; w < WT; ++w) dsm[(r * WT + w) * (C + 1) + ch0 + tid] = acc[w];
    }
  }
  __syncthreads();
  const int nw = TB / 32, ntok = rows * WT;
  for (int tk = warp; tk < ntok; tk += nw) {
    const float* dr = dsm + tk * (C + 1);
    float s = 0.f;
    for (int c = lane; c < C; c += 32) s += dr[c];
    const float mean = warp_sum(s) / C;
    float v = 0.f;
    for (int c = lane; c < C; c += 32) { float d = dr[c] - mean; v += d * d; }
    const float rstd = rsqrtf(warp_sum(v) / C + p.eps);
    const int r = tk / WT, w = tk - r * WT;
    const size_t m = ((size_t)b * H + h0 + r) * W + w0 + w;
    __half* out = p.a1 + m * C;
    for (int pp = lane; pp < C / 2; pp += 32) {
      const int c = 2 * pp;
      float a0 = (dr[c] - mean) * rstd * __ldg(p.lnw + c) + __ldg(p.lnb + c);
      float a1 = (dr[c + 1] - mean) * rstd * __ldg(p.lnw + c + 1) + __ldg(p.lnb + c + 1);
      *reinterpret_cast<uint32_t*>(out + c) = pack_h2(a0, a1);
    }
  }
}
